const config = {
  "previewFeatures": [],
  "clientVersion": "7.2.0",
  "engineVersion": "0c8ef2ce45c83248ab3df073180d5eda9e8be7a3",
  "activeProvider": "postgresql",
  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Looking for ways to speed up your queries, or scale easily with your serverless or edge functions?\n// Try Prisma Accelerate: https://pris.ly/cli/accelerate-init\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ==================================================================\n// Enums\n// ==================================================================\n\nenum AuthRole {\n  USER\n  ADMIN\n  SUPER_ADMIN\n  SUPPORT\n}\n\nenum DocumentType {\n  LOGO\n  BANNER\n  IMAGE\n  VIDEO\n  AUDIO\n  PDF\n  DOCUMENT\n  INVOICE\n  OTHER\n}\n\nenum OrganizationRole {\n  OWNER\n  STORE_MANAGER\n  ACCOUNTANT\n}\n\nenum StoreIndustry {\n  RESTAURANT\n  CAFE\n  BAR\n  HOTEL\n  SALON\n  SPA\n  RETAIL\n  BARBERSHOP\n  FITNESS\n  FOOD_TRUCK\n  CLEANING\n  OTHER\n}\n\nenum Language {\n  EN\n  EL\n  ES\n  FR\n  DE\n  IT\n  PT\n  TR\n  RU\n  AR\n  ZH\n}\n\n// Mirrors the Language markets above: EUR (eurozone), USD/GBP (English),\n// TRY (Turkey), RUB (Russia), AED (Arabic-market default), CNY (China).\nenum Currency {\n  EUR\n  USD\n  GBP\n  TRY\n  RUB\n  AED\n  CNY\n}\n\nenum QrCodeSelectionMode {\n  CHOOSE_ONE\n  CHOOSE_MANY\n  TEAM\n}\n\nenum DistributionRecipientType {\n  STORE\n  EMPLOYEE\n}\n\nenum TipStatus {\n  PENDING // deprecated in favor of CREATED; kept for backward compatibility with existing rows\n  CREATED\n  PROCESSING\n  COMPLETED\n  FAILED\n  CANCELLED\n  REFUNDED\n}\n\nenum PaymentTransactionStatus {\n  CREATED\n  PROCESSING\n  SUCCEEDED\n  FAILED\n  CANCELLED\n  EXPIRED\n}\n\nenum PayoutStatus {\n  PENDING\n  PROCESSING // claimed by an in-flight Payout run, awaiting the bank-transfer result\n  PAID\n  FAILED\n  CANCELLED // the parent Tip was refunded before this share was ever paid out\n}\n\nenum PayoutExecutionStatus {\n  PROCESSING\n  COMPLETED\n  FAILED\n  CANCELLED\n}\n\n// Connected-account lifecycle with the payment processor (e.g. Stripe\n// Connect onboarding), not to be confused with PayoutStatus above, which\n// tracks a single payout transaction.\nenum PayoutAccountStatus {\n  PENDING\n  ACTIVE\n  RESTRICTED\n  DISABLED\n}\n\nenum PayoutAccountOwnerType {\n  STORE\n  USER\n}\n\nenum PayoutMethod {\n  IBAN\n  CONNECTED_ACCOUNT // reserved for a future Marketplace-connected-account upgrade; not built in this phase\n}\n\nenum PaymentProvider {\n  VIVA\n  STRIPE\n  PAYPAL\n}\n\n// Where a Distribution Rule's money is actually sent. DIRECT pays every\n// recipient their own share to their own payout account. VIA_STORE sends\n// the whole tip to the Store's account instead, and the Store hands each\n// employee their share itself (cash, bank transfer, payroll — the method\n// is recorded but the money never moves through us). The rule's\n// percentages are unchanged either way: they still decide what each\n// employee earned, which under VIA_STORE is what the Store owes them.\nenum DistributionPayoutMode {\n  DIRECT\n  VIA_STORE\n}\n\n// Whether an employee has actually received a share the Store collected on\n// their behalf. Orthogonal to PayoutStatus above, which only tracks whether\n// the money left the platform: under VIA_STORE both axes move separately,\n// and the gap between them is the Store's debt to the employee.\nenum SettlementStatus {\n  NOT_REQUIRED // Store's own share, or an employee share paid directly to them\n  OWED\n  SETTLED\n  CANCELLED // the parent Tip was refunded before the Store handed the money over\n}\n\n// A correction against what a Store owes an employee — today only raised\n// when a Tip is refunded after its share was already handed over, since an\n// off-platform handover has no clawback. PROPOSED until the Store chooses\n// to apply it to a settlement.\nenum SettlementAdjustmentStatus {\n  PROPOSED\n  APPLIED\n  DISMISSED\n}\n\nenum ReviewSentiment {\n  POSITIVE\n  NEUTRAL\n  NEGATIVE\n}\n\nenum FeedbackQuestionType {\n  RATING\n  TEXT\n}\n\nenum RefundStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  COMPLETED\n}\n\nenum AlertType {\n  POSITIVE_COMPLIMENTS\n  NEGATIVE_SATISFACTION_DROP\n  LOW_RATING_REVIEW\n  PERFORMANCE_CHANGE\n  PAYOUT_REQUEST_APPROVED\n  PAYOUT_REQUEST_REJECTED\n}\n\n// A Store's request to be paid its accumulated tips, backed by an invoice it\n// issued to the platform. No PAID/FAILED values on purpose: \"paid\" is derived\n// from the linked Payout's status (owned by the Viva webhook), and a failed\n// transfer keeps the request PENDING_REVIEW with `failure_reason` set so an\n// admin can simply approve again.\nenum PayoutRequestStatus {\n  PENDING_REVIEW\n  APPROVED\n  REJECTED\n  CANCELLED\n}\n\nenum InvoiceCheckStatus {\n  PENDING\n  COMPLETED\n  FAILED\n  SKIPPED // AI check disabled in AppConfig, or no OpenAI key configured\n}\n\nenum InvoiceCheckVerdict {\n  MATCH\n  MISMATCH\n  UNREADABLE\n}\n\nenum SubscriptionPlan {\n  STARTER\n  PROFESSIONAL\n  ENTERPRISE\n}\n\nenum SubscriptionStatus {\n  TRIALING\n  ACTIVE\n  PAST_DUE\n  CANCELED\n}\n\n// ==================================================================\n// Identity — User: a real person identified by email.\n// Every Account type below (OrganizationMember, Employee, customer\n// activity on Tip/Review) links back to a User. A User row can exist\n// as a passwordless shell before the person ever registers.\n// ==================================================================\n\nmodel User {\n  id                String    @id @default(uuid())\n  email             String    @unique\n  phone             String?   @unique\n  first_name        String? // unset until the person registers or is otherwise captured (e.g. a Store adding them as staff by name)\n  last_name         String?\n  password          String? // null until the person sets a password; until then this row is a passive shell, not a login\n  role              AuthRole  @default(USER) // platform-level role (support/admin); unrelated to OrganizationRole, which is per Organization\n  registered_at     DateTime? // set the moment the person claims this identity by setting a password for the first time\n  is_email_verified Boolean   @default(false)\n  is_phone_verified Boolean   @default(false)\n  is_archived       Boolean   @default(false)\n  created_at        DateTime  @default(now())\n  updated_at        DateTime  @updatedAt\n\n  password_reset_tokens    PasswordResetToken[]\n  documents                Document[]\n  organization_memberships OrganizationMember[]\n  employee_accounts        Employee[]\n  customer_tips            Tip[]                  @relation(\"TipCustomer\")\n  customer_reviews         Review[]               @relation(\"ReviewCustomer\")\n  refunds_requested        Refund[]               @relation(\"RefundRequestedBy\")\n  refunds_processed        Refund[]               @relation(\"RefundProcessedBy\")\n  payout_account           PayoutAccount?\n  settlements_recorded     Settlement[]           @relation(\"SettlementRecordedBy\")\n  settlements_reversed     Settlement[]           @relation(\"SettlementReversedBy\")\n  settlement_adjustments   SettlementAdjustment[] @relation(\"SettlementAdjustmentCreatedBy\")\n  payout_requests_made     PayoutRequest[]        @relation(\"PayoutRequestRequestedBy\")\n  payout_requests_reviewed PayoutRequest[]        @relation(\"PayoutRequestReviewedBy\")\n\n  @@index([email])\n  @@index([phone])\n  @@map(\"users\")\n}\n\nmodel PasswordResetToken {\n  id         String    @id @default(uuid())\n  token_hash String    @unique\n  user_uuid  String\n  expires_at DateTime\n  used_at    DateTime?\n  created_at DateTime  @default(now())\n\n  user User @relation(fields: [user_uuid], references: [id], onDelete: Cascade)\n\n  @@index([user_uuid])\n  @@index([expires_at])\n  @@map(\"password_reset_tokens\")\n}\n\nmodel Document {\n  id         String       @id @default(uuid())\n  user_uuid  String\n  filename   String\n  mimetype   String\n  size       Int\n  url        String\n  path       String\n  type       DocumentType @default(LOGO)\n  created_at DateTime     @default(now())\n\n  user User @relation(fields: [user_uuid], references: [id], onDelete: Cascade)\n\n  stores_logo        Store[]        @relation(\"StoreLogoDocument\")\n  stores_cover       Store[]        @relation(\"StoreCoverDocument\")\n  organizations_logo Organization[] @relation(\"OrganizationLogoDocument\")\n  employees_photo    Employee[]     @relation(\"EmployeePhotoDocument\")\n  payout_request     PayoutRequest? // the invoice backing a payout request (Restrict: can't be deleted from under it)\n\n  @@index([user_uuid])\n  @@map(\"documents\")\n}\n\n// ==================================================================\n// Organizations & Stores\n// ==================================================================\n\nmodel Organization {\n  id               String  @id @default(uuid())\n  name             String\n  slug             String  @unique\n  is_active        Boolean @default(true)\n  logo_document_id String?\n  vat_number       String? // billing identity for invoicing — set via org settings, never inferred\n  legal_name       String? // registered legal entity name, may differ from the customer-facing `name`\n  profession       String? // declared business activity, shown on invoices (e.g. \"Restaurant\", \"Καφετέρια\")\n  doy              String? // Greek tax office (Δ.Ο.Υ.) — only relevant for Greek-registered organizations\n\n  // Registered billing address — the invoice-recipient address, independent\n  // of any Store's own (possibly different/multiple) physical address(es).\n  address_line String?\n  city         String?\n  country      String?\n  postal_code  String?\n  full_address Json?\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  logo_document Document? @relation(\"OrganizationLogoDocument\", fields: [logo_document_id], references: [id], onDelete: SetNull)\n\n  members      OrganizationMember[]\n  stores       Store[]\n  subscription Subscription?\n\n  @@index([slug])\n  @@map(\"organizations\")\n}\n\n// Organization Account: membership + role, scoped either at\n// the Organization level (store_id null) or a single Store (store_id set).\nmodel OrganizationMember {\n  id              String           @id @default(uuid())\n  organization_id String\n  user_id         String\n  role            OrganizationRole\n  store_id        String? // null = scoped to the whole Organization; set = scoped to just this one Store\n  created_at      DateTime         @default(now())\n  updated_at      DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  user         User         @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  store        Store?       @relation(fields: [store_id], references: [id], onDelete: Cascade)\n\n  @@unique([organization_id, user_id, store_id, role])\n  @@index([organization_id])\n  @@index([user_id])\n  @@index([store_id])\n  @@map(\"organization_members\")\n}\n\n// Billing: one subscription per Organization, covering every Store under it.\nmodel Subscription {\n  id                               String             @id @default(uuid())\n  organization_id                  String             @unique\n  plan                             SubscriptionPlan   @default(ENTERPRISE)\n  status                           SubscriptionStatus @default(TRIALING)\n  billing_provider_customer_id     String?\n  billing_provider_subscription_id String?\n  current_period_start             DateTime?\n  current_period_end               DateTime?\n  created_at                       DateTime           @default(now())\n  updated_at                       DateTime           @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@map(\"subscriptions\")\n}\n\n// A Store: fully self-contained — branding, employees, QR codes,\n// tipping/review config, tips, reviews, analytics.\nmodel Store {\n  id              String        @id @default(uuid())\n  organization_id String\n  name            String\n  slug            String        @unique\n  industry        StoreIndustry @default(OTHER)\n  is_active       Boolean       @default(true)\n\n  // Branding\n  logo_document_id  String?\n  cover_document_id String?\n  primary_color     String?\n  secondary_color   String?\n\n  // Customer-facing messages (§23, §24). Json map of lowercase Language\n  // code -> text, e.g. {\"en\": \"Welcome!\", \"el\": \"Καλώς ήρθατε!\"}; the\n  // primary_language key is always present, others are filled in as\n  // translations are produced.\n  welcome_message   Json?\n  thank_you_message Json?\n\n  // Address\n  full_address Json?\n  address_line String?\n  city         String?\n  country      String?\n  postal_code  String?\n  timezone     String  @default(\"UTC\")\n\n  // Localization\n  primary_language    Language   @default(EN)\n  supported_languages Language[] @default([EN])\n\n  // Tipping configuration\n  currency                Currency @default(EUR)\n  suggested_tip_amounts   Int[]    @default([200, 1000, 2000, 5000])\n  allow_custom_tip_amount Boolean  @default(true)\n\n  // DEPRECATED, no longer read: the VAT rate is now platform-wide (AppConfig.vat_rate_percentage).\n  vat_rate_percentage Decimal? @db.Decimal(5, 2)\n\n  // Review flow routing: above the threshold, prompt the customer to post\n  // a public review; below it, collect private feedback instead.\n  public_review_redirect_url     String?\n  public_review_rating_threshold Int?    @default(4)\n\n  // The rule applied when a tip doesn't come through a QR code with its own override.\n  // @unique because a rule can only ever be the default for the one store it belongs to.\n  default_distribution_rule_id String? @unique\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  organization              Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  logo_document             Document?         @relation(\"StoreLogoDocument\", fields: [logo_document_id], references: [id], onDelete: SetNull)\n  cover_document            Document?         @relation(\"StoreCoverDocument\", fields: [cover_document_id], references: [id], onDelete: SetNull)\n  default_distribution_rule DistributionRule? @relation(\"StoreDefaultDistributionRule\", fields: [default_distribution_rule_id], references: [id], onDelete: SetNull)\n\n  organization_members       OrganizationMember[]\n  employees                  Employee[]\n  spots                      Spot[]\n  qr_codes                   QrCode[]\n  qr_template_customizations QrTemplateCustomization[]\n  distribution_rules         DistributionRule[]        @relation(\"StoreDistributionRules\")\n  tips                       Tip[]\n  reviews                    Review[]\n  review_categories          ReviewCategory[]\n  review_tags                ReviewTag[]\n  feedback_questions         FeedbackQuestion[]\n  alert_preferences          AlertPreference[]\n  alerts                     Alert[]\n  insight_summaries          InsightSummary[]\n  payout_account             PayoutAccount?\n  payouts                    Payout[]\n  payout_requests            PayoutRequest[]\n  settlements                Settlement[]\n  settlement_adjustments     SettlementAdjustment[]\n\n  @@index([organization_id])\n  @@index([slug])\n  @@map(\"stores\")\n}\n\n// ==================================================================\n// Employees — the Employee Account.\n// ==================================================================\n\nmodel Employee {\n  id                String    @id @default(uuid())\n  store_id          String\n  user_id           String?\n  // Multilingual: Json map of lowercase Language code -> text, e.g.\n  // {\"en\": \"Maria Papadopoulou\", \"el\": \"Μαρία Παπαδοπούλου\"}. Auto-translated\n  // (stub) into every Store-supported language on create; hand-edited per\n  // language via full_name_translations on PATCH employees/:id.\n  full_name         Json\n  email             String\n  photo_document_id String?\n  position          String?\n  is_active         Boolean   @default(true)\n  invited_at        DateTime? // last time an account-setup invite email was sent to this Employee's User\n  created_at        DateTime  @default(now())\n  updated_at        DateTime  @updatedAt\n\n  store          Store     @relation(fields: [store_id], references: [id], onDelete: Cascade)\n  user           User?     @relation(fields: [user_id], references: [id], onDelete: SetNull)\n  photo_document Document? @relation(\"EmployeePhotoDocument\", fields: [photo_document_id], references: [id], onDelete: SetNull)\n\n  qr_codes                     QrCodeEmployee[]\n  distribution_rule_recipients DistributionRuleRecipient[]\n  tips                         Tip[]\n  tip_distributions            TipDistribution[]\n  reviews                      Review[]\n  alerts                       Alert[]\n  payouts                      Payout[]\n  settlements                  Settlement[]\n  settlement_adjustments       SettlementAdjustment[]\n\n  @@index([store_id])\n  @@index([user_id])\n  @@index([email])\n  @@map(\"employees\")\n}\n\n// ==================================================================\n// Spots — a Store's physical placements (a restaurant table, a spa bed,\n// a salon chair, a hotel room, the bar, reception, a checkout counter,\n// ...). Optional and many-to-many with QrCode: a QR can cover several\n// spots (e.g. one code printed for a whole patio zone) and a spot can\n// have several QR codes (e.g. one on the table, one on the receipt) or\n// none at all (a QR meant for an employee card or promotional material\n// has no spot).\n// ==================================================================\n\nmodel Spot {\n  id         String   @id @default(uuid())\n  store_id   String\n  name       String // e.g. \"Table 12\", \"Bed 3\", \"Room 204\", \"Bar\", \"Reception\"\n  is_active  Boolean  @default(true)\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  store Store @relation(fields: [store_id], references: [id], onDelete: Cascade)\n\n  qr_codes QrCodeSpot[]\n\n  @@index([store_id])\n  @@map(\"spots\")\n}\n\n// ==================================================================\n// QR Codes\n// ==================================================================\n\nmodel QrCode {\n  id                   String              @id @default(uuid())\n  store_id             String\n  code                 String              @unique // short code embedded in the scan URL, e.g. delitip.com/{store_slug}/q/{code}\n  label                String\n  // Only meaningful when 2+ employees are assigned below; ignored for 0 or 1.\n  // CHOOSE_ONE: customer picks exactly one to thank. CHOOSE_MANY: customer\n  // picks any subset; the tip splits only among those picked, the rule's\n  // percentages renormalized across just the selected employees. TEAM: no\n  // selection step, tip is split across all of them automatically.\n  selection_mode       QrCodeSelectionMode @default(CHOOSE_ONE)\n  is_active            Boolean             @default(true)\n  distribution_rule_id String? // override for this QR code only; null falls back to the store's default rule\n  created_at           DateTime            @default(now())\n  updated_at           DateTime            @updatedAt\n\n  store             Store             @relation(fields: [store_id], references: [id], onDelete: Cascade)\n  distribution_rule DistributionRule? @relation(fields: [distribution_rule_id], references: [id], onDelete: SetNull)\n\n  // Both optional and independent of each other: a QR can carry any number\n  // of spots and any number of employees. A QR with employees but no\n  // spots is effectively a portable/personal QR (e.g. an employee's own\n  // business card); a QR with spots is a location QR.\n  spots     QrCodeSpot[]\n  employees QrCodeEmployee[]\n  tips      Tip[]\n\n  @@index([store_id])\n  @@index([code])\n  @@index([distribution_rule_id])\n  @@map(\"qr_codes\")\n}\n\n// Join table: which spot(s) a QR code is placed at, if any.\nmodel QrCodeSpot {\n  id         String   @id @default(uuid())\n  qr_code_id String\n  spot_id    String\n  created_at DateTime @default(now())\n\n  qr_code QrCode @relation(fields: [qr_code_id], references: [id], onDelete: Cascade)\n  spot    Spot   @relation(fields: [spot_id], references: [id], onDelete: Cascade)\n\n  @@unique([qr_code_id, spot_id])\n  @@index([qr_code_id])\n  @@index([spot_id])\n  @@map(\"qr_code_spots\")\n}\n\n// Join table: which employee(s) a QR code can attribute a tip to.\nmodel QrCodeEmployee {\n  id          String   @id @default(uuid())\n  qr_code_id  String\n  employee_id String\n  created_at  DateTime @default(now())\n\n  qr_code  QrCode   @relation(fields: [qr_code_id], references: [id], onDelete: Cascade)\n  employee Employee @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n\n  @@unique([qr_code_id, employee_id])\n  @@index([qr_code_id])\n  @@index([employee_id])\n  @@map(\"qr_code_employees\")\n}\n\n// A store's saved edits to a printable QR template design (see the\n// frontend's QR_TEMPLATES registry for template_id values — not a DB enum,\n// so a new template doesn't need a migration). Shared across every QR code\n// belonging to the store: one customization per store per template design,\n// not per QR code — branding/layout is store-level, only the QR pixels and\n// scan URL vary per QR code.\nmodel QrTemplateCustomization {\n  id          String   @id @default(uuid())\n  store_id    String\n  template_id String\n  canvas      Json // TemplateCanvasConfig\n  elements    Json // TemplateElement[]\n  created_at  DateTime @default(now())\n  updated_at  DateTime @updatedAt\n\n  store Store @relation(fields: [store_id], references: [id], onDelete: Cascade)\n\n  @@unique([store_id, template_id])\n  @@index([store_id])\n  @@map(\"qr_template_customizations\")\n}\n\n// ==================================================================\n// Distribution Rules — how a tip is split between the Store and/or Employees.\n// ==================================================================\n\nmodel DistributionRule {\n  id          String                 @id @default(uuid())\n  store_id    String\n  name        String\n  // Whether this rule's shares are paid out to each recipient directly or\n  // collected into the Store's account for the Store to hand over itself.\n  // Absolute per rule — there is no per-employee override — but a Store can\n  // run rules of both modes side by side, since a QR code picks its own rule.\n  payout_mode DistributionPayoutMode @default(DIRECT)\n  created_at  DateTime               @default(now())\n  updated_at  DateTime               @updatedAt\n\n  store Store @relation(\"StoreDistributionRules\", fields: [store_id], references: [id], onDelete: Cascade)\n\n  recipients        DistributionRuleRecipient[]\n  default_for_store Store?                      @relation(\"StoreDefaultDistributionRule\")\n  qr_code_overrides QrCode[]\n  tips              Tip[]\n\n  @@unique([store_id, name])\n  @@index([store_id])\n  @@map(\"distribution_rules\")\n}\n\n// One line item of a Distribution Rule: a recipient (Store or a specific\n// Employee) and its share. A rule's recipients' percentages sum to 100.\nmodel DistributionRuleRecipient {\n  id                   String                    @id @default(uuid())\n  distribution_rule_id String\n  recipient_type       DistributionRecipientType\n  employee_id          String? // required when recipient_type is EMPLOYEE, null when recipient_type is STORE\n  percentage           Decimal                   @db.Decimal(5, 2) // 0-100; all recipients on a rule must sum to 100\n  sort_order           Int                       @default(0) // display order; the lowest sort_order recipient absorbs the rounding remainder on a split (§5)\n  created_at           DateTime                  @default(now())\n\n  distribution_rule DistributionRule @relation(fields: [distribution_rule_id], references: [id], onDelete: Cascade)\n  employee          Employee?        @relation(fields: [employee_id], references: [id], onDelete: Cascade)\n\n  @@index([distribution_rule_id])\n  @@index([employee_id])\n  @@map(\"distribution_rule_recipients\")\n}\n\n// ==================================================================\n// Tips & Payouts\n// ==================================================================\n\n// Payout destination at a payment processor. Owned by either a Store\n// (where it collects tips itself) or a User (a person's own connected\n// account, shared across every Employee Account they hold — see §11 —\n// since the processor ties one connected account to one person's\n// identity/KYC, not to a specific employment at one Store). Exactly one\n// of store_id/user_id is set, matching owner_type; the unique constraint\n// on each caps it at one payout account per owner.\nmodel PayoutAccount {\n  id                   String                 @id @default(uuid())\n  owner_type           PayoutAccountOwnerType\n  store_id             String?                @unique // set when owner_type is STORE\n  user_id              String?                @unique // set when owner_type is USER\n  provider             PaymentProvider        @default(VIVA)\n  provider_account_id  String // the connected account id with that processor\n  status               PayoutAccountStatus    @default(PENDING)\n  payout_method        PayoutMethod           @default(IBAN)\n  bank_account_id      String? // Viva's linked-bank-account id from the Bank Transfer API\n  iban_last4           String? // last 4 digits only — the raw IBAN is never persisted, see §16 of the payment plan\n  beneficiary_name     String?\n  connected_account_id String? // the provider's connected/seller account id (Viva Marketplace today; a future Stripe Connect account reuses this same generic column)\n  onboarding_url       String? // hosted-onboarding link shown to the owner until the connected account finishes verification\n  created_at           DateTime               @default(now())\n  updated_at           DateTime               @updatedAt\n\n  store   Store?   @relation(fields: [store_id], references: [id], onDelete: Cascade)\n  user    User?    @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  payouts Payout[]\n\n  @@map(\"payout_accounts\")\n}\n\nmodel Tip {\n  id                    String           @id @default(uuid())\n  store_id              String\n  qr_code_id            String\n  employee_id           String? // the single employee this tip was attributed to (one-employee QR or a Choose-one pick); null for store-only tips and Team-mode tips, which are split across `distributions` instead\n  distribution_rule_id  String? // the rule applied at the time of this tip; `distributions` holds the actual frozen amounts, so later edits to the rule can't retroactively change this tip\n  selected_employee_ids Json? // resolved at checkout time (Choose-many/Team); `distributions` aren't created until payment is confirmed, so this is what the webhook handler feeds into calculateTipDistribution()\n  customer_user_id      String? // customers are never required to identify themselves — these three fields stay null for anonymous tips\n  customer_email        String?\n  customer_name         String?\n  amount                Int // in the smallest currency unit (e.g. cents)\n  currency              Currency         @default(EUR)\n  status                TipStatus        @default(CREATED) // payment lifecycle of the tip itself, separate from payout_status on each TipDistribution\n  payment_provider      PaymentProvider? @default(VIVA)\n  payment_reference     String?\n  paid_at               DateTime?\n  created_at            DateTime         @default(now())\n  updated_at            DateTime         @updatedAt\n\n  store             Store             @relation(fields: [store_id], references: [id])\n  qr_code           QrCode            @relation(fields: [qr_code_id], references: [id])\n  employee          Employee?         @relation(fields: [employee_id], references: [id], onDelete: SetNull)\n  distribution_rule DistributionRule? @relation(fields: [distribution_rule_id], references: [id], onDelete: SetNull)\n  customer          User?             @relation(\"TipCustomer\", fields: [customer_user_id], references: [id], onDelete: SetNull)\n\n  distributions       TipDistribution[]\n  review              Review?\n  refunds             Refund[]\n  payment_transaction PaymentTransaction?\n\n  @@index([store_id])\n  @@index([qr_code_id])\n  @@index([employee_id])\n  @@index([customer_user_id])\n  @@index([status])\n  @@index([created_at])\n  @@index([status, created_at])\n  @@map(\"tips\")\n}\n\n// The real-money ledger row for a Tip: gross amount, provider order/transaction\n// references, and the fee/commission breakdown. 1:1 with Tip — created the\n// moment a checkout order is opened with the processor, finalized once the payment\n// webhook (or the reconciliation sweep) confirms the transaction.\nmodel PaymentTransaction {\n  id                             String                   @id @default(uuid())\n  tip_id                         String                   @unique\n  provider                       PaymentProvider          @default(VIVA)\n  client_request_id              String?                  @unique // idempotency key supplied by the frontend on POST /public/tips\n  provider_order_code            String?                  @unique // string, never numeric — Viva's 16-digit orderCode exceeds Number.MAX_SAFE_INTEGER\n  provider_transaction_id        String?                  @unique // Viva's transaction GUID (the 1796/1799 `TransactionId`) — what refunds and the 1799 fee webhook key on\n  provider_authorization_id      String? // the card authorization code (Viva `AuthorizationId`, e.g. \"870189\") — kept for reference/support, not unique across payments\n  tip_amount                     Int // the net, VAT-exclusive amount the customer selected — base for commission_amount and net_distributable_amount\n  vat_rate_percentage            Decimal?                 @db.Decimal(5, 2) // snapshotted from Store.vat_rate_percentage at creation time — never recomputed from live store config later\n  vat_amount                     Int? // round(tip_amount * vat_rate_percentage / 100) — retained by the platform in full, never distributed to store/employee\n  gross_amount                   Int // tip_amount + vat_amount — the VAT-inclusive total actually charged via Viva\n  currency                       Currency\n  commission_percentage_used     Decimal                  @db.Decimal(5, 2) // snapshotted from PlatformFinanceConfig at creation time — never recomputed from live config later\n  commission_amount              Int\n  platform_fee_percentage        Decimal                  @db.Decimal(5, 2) // commission_amount / tip_amount — the actual realized rate, distinct from the configured commission_percentage_used above (rounding can make them differ)\n  processor_fee_percentage_used  Decimal?                 @db.Decimal(5, 2) // snapshotted from PlatformFinanceConfig when processor_fee_estimated was computed — the processor-fee mirror of commission_percentage_used above; never recomputed from live config later, and stays unset for tips that never reached that step\n  processor_fee_fixed_used       Int? // minor units — the fixed part of the fee estimate (app_config) snapshotted alongside processor_fee_percentage_used\n  processor_fee_estimated        Int?\n  processor_fee_confirmed_amount Int?\n  processor_fee_confirmed        Boolean                  @default(false) // gates payout eligibility — a payout can never be computed from an estimate\n  payment_fee_percentage         Decimal?                 @db.Decimal(5, 2) // processor fee / gross_amount (VAT-inclusive — Viva's fee is charged on the full amount it processes), using whichever of the two fields above is current\n  total_fee_amount               Int? // commission_amount + processor fee (estimated until processor_fee_confirmed, then confirmed) — does NOT include vat_amount, which is tracked and retained separately\n  total_fee_percentage           Decimal?                 @db.Decimal(5, 2) // total_fee_amount / gross_amount\n  total_fee_percentage_sum       Decimal?                 @db.Decimal(5, 2) // platform_fee_percentage + processor fee / tip_amount — both rates on the tip base (VAT excluded), kept alongside total_fee_percentage as a cross-check since per-fee rounding can make them differ slightly\n  net_distributable_amount       Int? // tip_amount - total_fee_amount — what's actually split via distribution rules to store/employee; vat_amount never enters this pool\n  payment_method                 String?\n  status                         PaymentTransactionStatus @default(CREATED)\n  failure_reason                 String?\n  confirmed_at                   DateTime?\n  created_at                     DateTime                 @default(now())\n  updated_at                     DateTime                 @updatedAt\n\n  tip Tip @relation(fields: [tip_id], references: [id], onDelete: Cascade)\n\n  @@index([status])\n  @@index([provider])\n  @@map(\"payment_transactions\")\n}\n\n// Idempotency + audit log for every inbound Viva webhook. message_id is\n// Viva's own MessageId — the unique constraint is what makes at-least-once\n// delivery (Viva retries up to 24x hourly) safe to process.\nmodel WebhookEvent {\n  id               String          @id @default(uuid())\n  provider         PaymentProvider @default(VIVA)\n  message_id       String          @unique\n  event_type_id    Int\n  payload          Json\n  processed_at     DateTime?\n  processing_error String?\n  created_at       DateTime        @default(now())\n\n  @@index([event_type_id])\n  @@map(\"webhook_events\")\n}\n\n// The frozen, per-recipient breakdown of a Tip at the moment it was paid —\n// so later changes to a Distribution Rule never affect past tips, and\n// each recipient's payout can be tracked independently.\nmodel TipDistribution {\n  id                String                    @id @default(uuid())\n  tip_id            String\n  recipient_type    DistributionRecipientType\n  employee_id       String? // required when recipient_type is EMPLOYEE, null when recipient_type is STORE\n  amount            Int // this recipient's frozen share of the tip, in the smallest currency unit (rounding remainder goes to the first-listed recipient)\n  percentage        Decimal                   @db.Decimal(5, 2) // the rule's percentage at the time this tip was made\n  // Frozen copy of the rule's payout_mode, for the same reason `percentage`\n  // is frozen: the rule can be edited later, but only rows that haven't been\n  // claimed or settled yet are ever re-routed (see DistributionRulesService).\n  payout_mode       DistributionPayoutMode    @default(DIRECT)\n  payout_status     PayoutStatus              @default(PENDING) // whether this recipient's share has actually been paid out — independent of the Tip's own status\n  payout_id         String? // set only inside the atomic claim of a Payout run; null while PENDING/unclaimed\n  // Set when the Store locks this share into an invoice-backed PayoutRequest.\n  // A locked row is invisible to every other payout path (self-service runs,\n  // rule re-routing) until the request is approved, rejected or cancelled.\n  payout_request_id String?\n  paid_out_at       DateTime?\n  // Second, independent axis: under VIA_STORE the money reaching the Store's\n  // bank (payout_status) is not the employee receiving it (settlement_status).\n  settlement_status SettlementStatus          @default(NOT_REQUIRED)\n  settlement_id     String? // set only inside the atomic claim of a Settlement; null while OWED/unsettled\n  settled_at        DateTime?\n  created_at        DateTime                  @default(now())\n\n  tip            Tip            @relation(fields: [tip_id], references: [id], onDelete: Cascade)\n  employee       Employee?      @relation(fields: [employee_id], references: [id], onDelete: SetNull)\n  payout         Payout?        @relation(fields: [payout_id], references: [id], onDelete: SetNull)\n  payout_request PayoutRequest? @relation(fields: [payout_request_id], references: [id], onDelete: SetNull)\n  settlement     Settlement?    @relation(fields: [settlement_id], references: [id], onDelete: SetNull)\n\n  @@index([tip_id])\n  @@index([employee_id])\n  @@index([payout_status])\n  @@index([payout_id])\n  @@index([payout_request_id])\n  @@index([settlement_id])\n  @@index([employee_id, settlement_status])\n  @@map(\"tip_distributions\")\n}\n\n// One Bank Transfer API execution to one recipient (Store or Employee),\n// covering one or more TipDistribution rows accumulated since the last\n// payout for that recipient. Created only by a manual \"Pay out now\" run\n// (§10 of the payment plan) — there is no scheduled batch job in this phase.\nmodel Payout {\n  id                   String                    @id @default(uuid())\n  recipient_type       DistributionRecipientType\n  store_id             String?\n  employee_id          String?\n  payout_account_id    String\n  amount               Int\n  currency             Currency\n  provider             PaymentProvider           @default(VIVA)\n  provider_transfer_id String? // Viva bank-transfer commandId\n  status               PayoutExecutionStatus     @default(PROCESSING)\n  failure_reason       String?\n  executed_at          DateTime?\n  created_at           DateTime                  @default(now())\n  updated_at           DateTime                  @updatedAt\n\n  store          Store?            @relation(fields: [store_id], references: [id])\n  employee       Employee?         @relation(fields: [employee_id], references: [id])\n  payout_account PayoutAccount     @relation(fields: [payout_account_id], references: [id])\n  distributions  TipDistribution[]\n  payout_request PayoutRequest? // set when this payout was executed by approving an invoice-backed request\n\n  @@index([status])\n  @@index([store_id])\n  @@index([employee_id])\n  @@map(\"payouts\")\n}\n\n// ==================================================================\n// Payout requests — when AppConfig.payout_invoice_required is on, a Store's\n// own money (its STORE shares plus pooled VIA_STORE staff shares) can only\n// leave the platform through one of these: the Store issues an invoice to\n// the platform for the exact payable amount, an admin reviews it (helped by\n// an automatic AI read of the invoice), and approval executes the Viva\n// transfer. Every amount/period below is a frozen snapshot of the rows\n// locked at submission time.\n// ==================================================================\n\nmodel PayoutRequest {\n  id                   String              @id @default(uuid())\n  store_id             String\n  requested_by_user_id String?\n  status               PayoutRequestStatus @default(PENDING_REVIEW)\n\n  // Snapshot of the locked STORE group\n  amount                Int // what the Store must invoice and will receive (minor units)\n  own_share_amount      Int // the Store's own shares\n  held_for_staff_amount Int // pooled VIA_STORE shares it hands to staff off-platform\n  currency              Currency\n  distribution_count    Int\n  period_from           DateTime // oldest tip.paid_at among the locked rows\n  period_to             DateTime // newest tip.paid_at among the locked rows\n  hold_cutoff_at        DateTime // now - payout_hold_window_hours at submission\n\n  // The invoice\n  invoice_document_id String  @unique // one upload backs exactly one request\n  invoice_number      String? // typed by the Store, optional\n  store_note          String?\n  failure_reason      String? // last Viva transfer failure; request stays PENDING_REVIEW so admin can retry\n\n  // Automatic invoice read (advisory only — approval is always a human action)\n  check_status    InvoiceCheckStatus   @default(PENDING)\n  check_verdict   InvoiceCheckVerdict?\n  check_issues    Json? // string[] of issue codes, see invoice-verification.utils.ts\n  check_extracted Json? // raw object the model extracted\n  check_model     String?\n  check_cost_usd  Decimal?             @db.Decimal(10, 6)\n  checked_at      DateTime?\n\n  // Review\n  reviewed_by_user_id String?\n  reviewed_at         DateTime?\n  admin_note          String?\n  payout_id           String?   @unique\n\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  store            Store             @relation(fields: [store_id], references: [id], onDelete: Cascade)\n  requested_by     User?             @relation(\"PayoutRequestRequestedBy\", fields: [requested_by_user_id], references: [id], onDelete: SetNull)\n  reviewed_by      User?             @relation(\"PayoutRequestReviewedBy\", fields: [reviewed_by_user_id], references: [id], onDelete: SetNull)\n  invoice_document Document          @relation(fields: [invoice_document_id], references: [id], onDelete: Restrict)\n  payout           Payout?           @relation(fields: [payout_id], references: [id], onDelete: SetNull)\n  distributions    TipDistribution[]\n\n  @@index([store_id, status])\n  @@index([status, created_at])\n  @@map(\"payout_requests\")\n}\n\n// One recorded handover from a Store to an employee, covering the shares the\n// Store collected on that employee's behalf under a VIA_STORE rule. The money\n// itself never moves through us — this is the record that it moved, so the\n// Store knows what it still owes and the employee can verify what they got.\n// Never deleted, only reversed.\nmodel Settlement {\n  id                       String    @id @default(uuid())\n  store_id                 String\n  employee_id              String?\n  employee_name_snapshot   String // an employee row can be detached (TipDistribution.employee_id is SetNull) but the debt record must outlive it\n  amount                   Int // derived server-side from the settled distributions minus applied adjustments, never supplied by the client\n  currency                 Currency\n  settled_at               DateTime // when the Store says the handover happened, which may predate the bank transfer reaching them\n  note                     String?\n  reference                String? // the Store's own reference, e.g. a payroll run or bank transfer id\n  recorded_by_user_id      String?\n  confirmed_by_employee_at DateTime? // the employee's own acknowledgement that they received it\n  reversed_at              DateTime?\n  reversed_by_user_id      String?\n  created_at               DateTime  @default(now())\n  updated_at               DateTime  @updatedAt\n\n  store       Store     @relation(fields: [store_id], references: [id], onDelete: Cascade)\n  employee    Employee? @relation(fields: [employee_id], references: [id], onDelete: SetNull)\n  recorded_by User?     @relation(\"SettlementRecordedBy\", fields: [recorded_by_user_id], references: [id], onDelete: SetNull)\n  reversed_by User?     @relation(\"SettlementReversedBy\", fields: [reversed_by_user_id], references: [id], onDelete: SetNull)\n\n  distributions TipDistribution[]\n  adjustments   SettlementAdjustment[]\n\n  @@index([store_id])\n  @@index([employee_id])\n  @@index([settled_at])\n  @@map(\"settlements\")\n}\n\n// A correction against what a Store owes an employee, held as a negative\n// amount. Raised automatically when a Tip is refunded after its share was\n// already settled — an off-platform handover has no clawback, so the only\n// remedy is to deduct it from what the Store hands over next.\nmodel SettlementAdjustment {\n  id                 String                     @id @default(uuid())\n  store_id           String\n  employee_id        String?\n  amount             Int // negative minor units\n  reason             String\n  refund_id          String?\n  status             SettlementAdjustmentStatus @default(PROPOSED)\n  settlement_id      String? // set when the Store applies it to a settlement\n  created_by_user_id String?\n  created_at         DateTime                   @default(now())\n  updated_at         DateTime                   @updatedAt\n\n  store      Store       @relation(fields: [store_id], references: [id], onDelete: Cascade)\n  employee   Employee?   @relation(fields: [employee_id], references: [id], onDelete: SetNull)\n  refund     Refund?     @relation(fields: [refund_id], references: [id], onDelete: SetNull)\n  settlement Settlement? @relation(fields: [settlement_id], references: [id], onDelete: SetNull)\n  created_by User?       @relation(\"SettlementAdjustmentCreatedBy\", fields: [created_by_user_id], references: [id], onDelete: SetNull)\n\n  @@index([store_id])\n  @@index([employee_id])\n  @@index([status])\n  @@index([settlement_id])\n  @@map(\"settlement_adjustments\")\n}\n\nmodel Refund {\n  id                             String       @id @default(uuid())\n  tip_id                         String\n  amount                         Int\n  reason                         String?\n  status                         RefundStatus @default(PENDING)\n  requested_by_user_id           String? // who asked for the refund — often the customer, sometimes a store manager acting for them\n  processed_by_user_id           String? // who approved/executed it, e.g. a Store Manager or Accountant\n  provider_reference             String? // Viva's transactionId for the refund/fast-refund/rebate call\n  provider_status                String? // Viva's own status for that reference, finalized once the 1797 webhook confirms\n  requires_manual_reconciliation Boolean      @default(false) // set when a refund was approved on a tip whose distributions were already paid out — IBAN transfers have no automatic clawback\n  created_at                     DateTime     @default(now())\n  updated_at                     DateTime     @updatedAt\n\n  tip          Tip   @relation(fields: [tip_id], references: [id], onDelete: Cascade)\n  requested_by User? @relation(\"RefundRequestedBy\", fields: [requested_by_user_id], references: [id], onDelete: SetNull)\n  processed_by User? @relation(\"RefundProcessedBy\", fields: [processed_by_user_id], references: [id], onDelete: SetNull)\n\n  settlement_adjustments SettlementAdjustment[]\n\n  @@index([tip_id])\n  @@index([status])\n  @@map(\"refunds\")\n}\n\n// ==================================================================\n// Reviews & Feedback\n// ==================================================================\n\nmodel Review {\n  id                            String           @id @default(uuid())\n  store_id                      String\n  tip_id                        String?          @unique // the tip this review followed, if any — a review doesn't strictly require a tip\n  employee_id                   String?\n  customer_user_id              String?\n  customer_email                String?\n  customer_name                 String?\n  rating                        Int\n  comment                       String?\n  sentiment                     ReviewSentiment? // auto-categorized from the rating/comment; null until that analysis has run\n  redirected_to_public_platform Boolean          @default(false) // whether the customer was sent on to the store's public review platform after this review\n  created_at                    DateTime         @default(now())\n  updated_at                    DateTime         @updatedAt\n\n  store    Store     @relation(fields: [store_id], references: [id])\n  tip      Tip?      @relation(fields: [tip_id], references: [id], onDelete: SetNull)\n  employee Employee? @relation(fields: [employee_id], references: [id], onDelete: SetNull)\n  customer User?     @relation(\"ReviewCustomer\", fields: [customer_user_id], references: [id], onDelete: SetNull)\n\n  category_ratings   ReviewCategoryRating[]\n  feedback_responses FeedbackResponse[]\n  tags               ReviewTagAssignment[]\n\n  @@index([store_id])\n  @@index([employee_id])\n  @@index([customer_user_id])\n  @@index([rating])\n  @@index([created_at])\n  @@map(\"reviews\")\n}\n\n// Store-configurable rating categories, e.g. Friendliness, Speed, Professionalism.\nmodel ReviewCategory {\n  id         String   @id @default(uuid())\n  store_id   String\n  name       Json // §24: language code -> text, e.g. {\"en\": \"Friendliness\", \"el\": \"Φιλικότητα\"}\n  is_active  Boolean  @default(true)\n  sort_order Int      @default(0)\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  store   Store                  @relation(fields: [store_id], references: [id], onDelete: Cascade)\n  ratings ReviewCategoryRating[]\n\n  @@index([store_id])\n  @@map(\"review_categories\")\n}\n\nmodel ReviewCategoryRating {\n  id                 String   @id @default(uuid())\n  review_id          String\n  review_category_id String\n  rating             Int\n  created_at         DateTime @default(now())\n\n  review          Review         @relation(fields: [review_id], references: [id], onDelete: Cascade)\n  review_category ReviewCategory @relation(fields: [review_category_id], references: [id], onDelete: Cascade)\n\n  @@unique([review_id, review_category_id])\n  @@index([review_id])\n  @@index([review_category_id])\n  @@map(\"review_category_ratings\")\n}\n\n// Store-scoped topic tags used to auto-categorize review content (§19/§20),\n// e.g. \"Friendly service\", \"Slow service\", \"Waiting time\". Distinct from\n// ReviewCategory (a star-rating question the customer answers): a tag is\n// applied afterward, by the store or by AI analysis, to summarize what a\n// review was actually about.\nmodel ReviewTag {\n  id         String           @id @default(uuid())\n  store_id   String\n  name       String\n  sentiment  ReviewSentiment? // which bucket this tag falls under (§19: Positive / Negative); null if unbucketed\n  is_active  Boolean          @default(true)\n  created_at DateTime         @default(now())\n  updated_at DateTime         @updatedAt\n\n  store   Store                 @relation(fields: [store_id], references: [id], onDelete: Cascade)\n  reviews ReviewTagAssignment[]\n\n  @@unique([store_id, name])\n  @@index([store_id])\n  @@map(\"review_tags\")\n}\n\nmodel ReviewTagAssignment {\n  id            String   @id @default(uuid())\n  review_id     String\n  review_tag_id String\n  created_at    DateTime @default(now())\n\n  review     Review    @relation(fields: [review_id], references: [id], onDelete: Cascade)\n  review_tag ReviewTag @relation(fields: [review_tag_id], references: [id], onDelete: Cascade)\n\n  @@unique([review_id, review_tag_id])\n  @@index([review_id])\n  @@index([review_tag_id])\n  @@map(\"review_tag_assignments\")\n}\n\n// Store-configurable feedback questions, e.g. \"How was the food?\".\nmodel FeedbackQuestion {\n  id         String               @id @default(uuid())\n  store_id   String\n  question   Json // §24: language code -> text, e.g. {\"en\": \"How was the food?\", \"el\": \"...\"}\n  type       FeedbackQuestionType @default(RATING)\n  is_active  Boolean              @default(true)\n  sort_order Int                  @default(0)\n  created_at DateTime             @default(now())\n  updated_at DateTime             @updatedAt\n\n  store     Store              @relation(fields: [store_id], references: [id], onDelete: Cascade)\n  responses FeedbackResponse[]\n\n  @@index([store_id])\n  @@map(\"feedback_questions\")\n}\n\nmodel FeedbackResponse {\n  id                   String   @id @default(uuid())\n  feedback_question_id String\n  review_id            String\n  // Exactly one of these is populated, matching the parent FeedbackQuestion's type: RATING → rating_value, TEXT → text_value.\n  rating_value         Int?\n  text_value           String?\n  created_at           DateTime @default(now())\n\n  feedback_question FeedbackQuestion @relation(fields: [feedback_question_id], references: [id], onDelete: Cascade)\n  review            Review           @relation(fields: [review_id], references: [id], onDelete: Cascade)\n\n  @@index([feedback_question_id])\n  @@index([review_id])\n  @@map(\"feedback_responses\")\n}\n\n// ==================================================================\n// Alerts\n// ==================================================================\n\nmodel AlertPreference {\n  id         String    @id @default(uuid())\n  store_id   String\n  alert_type AlertType\n  is_enabled Boolean   @default(true)\n  created_at DateTime  @default(now())\n  updated_at DateTime  @updatedAt\n\n  store Store @relation(fields: [store_id], references: [id], onDelete: Cascade)\n\n  @@unique([store_id, alert_type])\n  @@index([store_id])\n  @@map(\"alert_preferences\")\n}\n\n// A single triggered alert instance, generated for a Store when one of its enabled AlertPreferences fires.\nmodel Alert {\n  id          String    @id @default(uuid())\n  store_id    String\n  type        AlertType\n  title       String\n  message     String\n  employee_id String?\n  is_read     Boolean   @default(false)\n  created_at  DateTime  @default(now())\n\n  store    Store     @relation(fields: [store_id], references: [id], onDelete: Cascade)\n  employee Employee? @relation(fields: [employee_id], references: [id], onDelete: SetNull)\n\n  @@index([store_id])\n  @@index([employee_id])\n  @@map(\"alerts\")\n}\n\n// ==================================================================\n// AI Feedback Analysis — periodic auto-generated summaries of\n// customer feedback for a Store.\n// ==================================================================\n\nmodel InsightSummary {\n  id                          String   @id @default(uuid())\n  store_id                    String\n  period_start                DateTime\n  period_end                  DateTime\n  summary                     String\n  satisfaction_change_percent Decimal? @db.Decimal(5, 2)\n  top_praise                  String?\n  top_complaint               String?\n  created_at                  DateTime @default(now())\n\n  store Store @relation(fields: [store_id], references: [id], onDelete: Cascade)\n\n  @@index([store_id])\n  @@index([period_start, period_end])\n  @@map(\"insight_summaries\")\n}\n\n// ==================================================================\n// App Config — platform-wide finance settings, editable at runtime by\n// ADMIN / SUPER_ADMIN. Singleton: exactly one row, id \"default\".\n// ==================================================================\n\nmodel AppConfig {\n  id                                      String   @id @default(\"default\")\n  tip_platform_commission_percentage      Decimal  @default(5) @db.Decimal(5, 2)\n  tip_processor_fee_estimate_percentage   Decimal  @default(2.4) @db.Decimal(5, 2)\n  tip_processor_fee_estimate_fixed_amount Int      @default(26) // minor units (€0.26)\n  payout_hold_window_hours                Int      @default(48)\n  vat_rate_percentage                     Decimal  @default(0) @db.Decimal(5, 2) // added on top of each tip at checkout; 0 = no VAT\n  // Invoice-gated payouts: when on, a Store's own money is only paid through\n  // an admin-reviewed PayoutRequest backed by an invoice to the platform.\n  payout_invoice_required                 Boolean  @default(false)\n  payout_invoice_ai_check_enabled         Boolean  @default(true) // read the invoice with OpenAI and flag mismatches for the admin\n  connected_account_payouts_enabled       Boolean  @default(false) // rollout switch for Viva Marketplace (connected-account) Store payouts\n  tip_payouts_store_only                  Boolean  @default(true) // tips are only transferred to stores for now; hides staff (direct employee) payout actions\n  platform_legal_name                     String? // the platform's own invoicing identity, shown to Stores so they know who to invoice\n  platform_vat_number                     String?\n  platform_tax_office                     String?\n  platform_address                        String?\n  payout_invoice_instructions             String? // free text shown to Stores next to the invoice details\n  updated_by_user_id                      String?\n  created_at                              DateTime @default(now())\n  updated_at                              DateTime @updatedAt\n\n  @@map(\"app_config\")\n}\n"
}

